export function translateStudent(
  locale: StudentLocale,
  key: string,
  values?: Record<string, string | number>,
): string {
  const dict = locale === "uk" ? UK_STRINGS : KO_STRINGS;
  let text = dict[key] ?? KO_STRINGS[key] ?? key;
  if (values) {
    for (const [k, v] of Object.entries(values)) {
      text = text.replaceAll(`{${k}}`, String(v));
    }
  }
  return text;
}
